int Sum(std::span<const int> values) {
  int total = 0;
  for (int value : values) total += value;
  return total;
}
int readings[]{4, 8};
int total = Sum(readings);
// Массив жив во время вызова; Sum читает его элементы без копирования массива.
// Возвращается отдельное число; представление нигде не сохраняется.

int n = 5;
